package com.bananalab.lite;
import org.json.*;import java.io.*;import java.nio.file.*;import java.util.*;import java.util.zip.*;
public final class Stage70DiskKnowledgeCheck{
 static void check(boolean b,String s){if(!b)throw new AssertionError(s);}
 static Reader large(final int chars,final String tail){return new Reader(){int at;String block="Registro de archivo antiguo sin datos del término nuevo. ";public int read(char[] b,int o,int n){if(at>=chars+tail.length())return -1;int size=Math.min(n,chars+tail.length()-at);for(int i=0;i<size;i++,at++)b[o+i]=at<chars?block.charAt(at%block.length()):tail.charAt(at-chars);return size;}public void close(){}};}
 static NotebookDisk fresh()throws Exception{return new NotebookDisk(Files.createTempDirectory("banana-disk-test").toFile(),new NotebookMemoryIndex());}
 static byte[] contents(File f)throws Exception{return Files.readAllBytes(f.toPath());}
 static String answer(NotebookDisk disk,String query)throws Exception{return ReadingKnowledge.answer(disk.selected(query),query);}
 public static void main(String[] args)throws Exception{
  CreatorPersistenceCheck.Fake c=new CreatorPersistenceCheck.Fake();JSONObject legacy=KnowledgeNotebook.entry("Antes","La alferina es una tinta ficticia de color verde.","https://example.com/antes","web",1);KnowledgeNotebook.prefs(c).edit().putString("entries",new JSONArray().put(legacy).toString()).putString("last",legacy.getString("id")).commit();NotebookDisk disk=NotebookDisk.of(c);check(!KnowledgeNotebook.prefs(c).contains("entries")&&disk.index.count()==1&&answer(disk,"que es la alferina").contains("tinta ficticia"),"legacy migrated and preferences retired only after indexed copy");
  disk.put("Libro completo",large(1200000,". La hiperlemia es una señal ficticia que conserva la clave Olmo923."),"https://example.com/libro","web");check(disk.index.bytes()>1200000&&answer(disk,"que es la hiperlemia").contains("Olmo923"),"million-character streamed source tail retrieved");JSONArray selected=disk.selected("que es la hiperlemia");check(selected.toString().length()<100000,"retrieval returns a bounded selection, not the complete document");try{disk.legacyRows();throw new AssertionError("silently omitted large source");}catch(IOException expected){check(ChatLanguage.normalize(expected.getMessage()).contains("respalda"),"legacy backup explains scalable archive");}
  File archive=new File(Files.createTempDirectory("banana-archive-test").toFile(),"knowledge.zip");NotebookArchive.write(disk,archive);NotebookDisk restored=fresh();try(InputStream in=new FileInputStream(archive)){NotebookArchive.restore(restored,in,false);}check(restored.index.bytes()==disk.index.bytes()&&answer(restored,"que es la hiperlemia").contains("Olmo923"),"full archive restores long source and searchable index");
  NotebookDisk.Doc longDoc=null;for(NotebookDisk.Doc d:restored.index.list(10))if(d.chars>1000000)longDoc=d;check(longDoc!=null&&Arrays.equals(contents(restored.file(longDoc)),contents(disk.file(disk.index.get(longDoc.id)))),"full UTF8 text identical after restoration");
  String privateVersion="La alferina es una tinta ficticia roja corregida por el usuario.";restored.put("Privado",new StringReader(privateVersion),"https://example.com/antes","web");try(InputStream in=new FileInputStream(archive)){NotebookArchive.restore(restored,in,false);}check(answer(restored,"que es la alferina").contains("roja"),"restore keeps private version of same source");
  int count=restored.index.count();long generation=restored.generation();try{restored.put("Fallido",new Reader(){int n;public int read(char[] b,int o,int size)throws IOException{if(n++>0)throw new IOException("lectura incompleta");Arrays.fill(b,o,o+size,'x');return size;}public void close(){}},"https://example.com/antes","web");throw new AssertionError("partial read");}catch(IOException expected){}check(restored.index.count()==count&&restored.generation()==generation&&answer(restored,"que es la alferina").contains("roja"),"failed streaming write preserves committed source");
  NotebookDisk empty=fresh();empty.clear();try(InputStream in=new FileInputStream(archive)){NotebookArchive.restore(empty,in,true);}check(empty.index.count()==0,"explicitly cleared library is not resurrected by automatic bootstrap");
  File bad=new File(archive.getParentFile(),"bad.zip");try(ZipInputStream in=new ZipInputStream(new FileInputStream(archive));ZipOutputStream out=new ZipOutputStream(new FileOutputStream(bad))){ZipEntry e;while((e=in.getNextEntry())!=null){NotebookArchive.entry(out,e.getName());if(e.getName().equals("manifest.json")){JSONObject m=new JSONObject(new String(NotebookArchive.limited(in,NotebookArchive.MANIFEST_LIMIT),"UTF-8"));m.getJSONArray("documents").getJSONObject(0).put("sha256",String.join("",Collections.nCopies(64,"0")));out.write(m.toString().getBytes("UTF-8"));}else{byte[] buffer=new byte[4096];int n;while((n=in.read(buffer))!=-1)out.write(buffer,0,n);}out.closeEntry();}}
  NotebookDisk target=fresh();target.put("Seguro",new StringReader("La segurina es una llave ficticia que debe conservarse intacta."),"user","user");try(InputStream in=new FileInputStream(bad)){NotebookArchive.restore(target,in,false);throw new AssertionError("corrupt archive accepted");}catch(IOException expected){}check(target.index.count()==1&&answer(target,"que es la segurina").contains("intacta"),"checksum failure imports no partial batch");
  String unicode="Inicio "+String.join("",Collections.nCopies(2040,"a"))+"🌱 fin con texto completo y acentos: árbol.";target.put("Unicode",new StringReader(unicode),"user","user");NotebookDisk.Doc last=target.index.get(target.index.meta("last"));check(new String(contents(target.file(last)),"UTF-8").equals(unicode),"surrogate and accents preserved in full file");
  check(NotebookDisk.terms("Árboles y plantas").equals(ReadingKnowledge.words("Árboles y plantas")),"index query normalization parity");
  check(KnowledgeNotebook.parse("aprende de un archivo").kind.equals("file")&&KnowledgeNotebook.parse("respalda mi conocimiento").kind.equals("export")&&KnowledgeNotebook.parse("restaura mis conocimientos").kind.equals("import"),"natural file/backup actions");
  System.out.println("PASS Stage70 streamed million-character storage, bounded retrieval, migration, complete archive, checksum rollback, private precedence, clear marker and Unicode");
 }
}
